            };
            let to_value_expr = if *block {
                quote! {
                    match #to_value_expr {
                        ::semio_framework_dsl_record::FieldValue::Absent => ::semio_framework_dsl_record::FieldValue::Absent,
                        other => ::semio_framework_dsl_record::FieldValue::Block(Box::new(other)),
