                },
                FieldKind::VecTuple(_) => quote! {
                    {
                        let mut __items = Vec::with_capacity(#ident.len());
                        for v in #ident.iter() { __items.push(::semio_framework_dsl_record::DslField::to_value(v)); }
                        ::semio_framework_dsl_record::FieldValue::Tuple(__items)
